query FindManyTaskTargets($filter: TaskTargetFilterInput, $orderBy: [TaskTargetOrderByInput], $lastCursor: String, $limit: Int, $offset: Int) {
  taskTargets(
    filter: $filter
    orderBy: $orderBy
    first: $limit
    after: $lastCursor
    offset: $offset
  ) {
    edges {
      node {
        __typename
        createdAt
        id
        task {
          __typename
          assigneeId
          bodyV2 {
            blocknote
            markdown
            tiptap
            __typename
          }
          createdAt
          createdBy {
            source
            workspaceMemberId
            name
            context {
              provider
              applicationId
              __typename
            }
            __typename
          }
          deletedAt
          dueAt
          id
          position
          status
          taskTargets {
            edges {
              node {
                __typename
                createdAt
                createdBy {
                  source
                  workspaceMemberId
                  name
                  context {
                    provider
                    applicationId
                    __typename
                  }
                  __typename
                }
                deletedAt
                id
                position
                targetCompany {
                  __typename
                  domainName {
                    primaryLinkUrl
                    primaryLinkLabel
                    secondaryLinks {
                      label
                      url
                      __typename
                    }
                    __typename
                  }
                  id
                  name
                }
                targetCompanyId
                targetOpportunity {
                  __typename
                  id
                  name
                }
                targetOpportunityId
                targetPerson {
                  __typename
                  avatarFile {
                    fileId
                    label
                    extension
                    url
                    __typename
                  }
                  id
                  name {
                    firstName
                    lastName
                    __typename
                  }
                }
                targetPersonId
                task {
                  __typename
                  id
                  title
                }
                taskId
                updatedAt
                updatedBy {
                  source
                  workspaceMemberId
                  name
                  context {
                    provider
                    applicationId
                    __typename
                  }
                  __typename
                }
              }
              __typename
            }
            __typename
          }
          title
          updatedAt
          updatedBy {
            source
            workspaceMemberId
            name
            context {
              provider
              applicationId
              __typename
            }
            __typename
          }
        }
        taskId
        updatedAt
      }
      cursor
      __typename
    }
    pageInfo {
      hasNextPage
      hasPreviousPage
      startCursor
      endCursor
      __typename
    }
    totalCount
    __typename
  }
}
